const{get,send}=require("./_firebase");module.exports=async(req,res)=>{if(req.method!=="POST")return send(res,405,{error:"Method not allowed"});try{if(!process.env.TORANEX_BOOTSTRAP_SECRET||req.headers["x-bootstrap-secret"]!==process.env.TORANEX_BOOTSTRAP_SECRET)return send(res,403,{error:"Invalid bootstrap secret"});const{db,auth}=get(),existing=await db.collection("admins").limit(1).get();if(!existing.empty)return send(res,409,{error:"Bootstrap is closed; an admin already exists"});const email=String(req.body?.email||"").trim().toLowerCase();if(!email)return send(res,400,{error:"Email required"});const u=await auth.getUserByEmail(email);await db.collection("admins").doc(u.uid).create({active:true,role:"OWNER",email:u.email,createdAt:new Date()});await db.collection("auditLogs").add({actorUid:u.uid,actorEmail:u.email,action:"bootstrap-owner",createdAt:new Date()});return send(res,201,{ok:true,uid:u.uid,email:u.email,message:"احذف TORANEX_BOOTSTRAP_SECRET من Vercel الآن ثم أعد النشر"});}catch(e){return send(res,500,{error:e.message||"Bootstrap failed"});}};